import{_ as e,o as i,c as a,a2 as s}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse(`{"title":"What is ApptiveScript","description":"ApptiveGrid's expression language — where it shows up, what it can do, and what it can't.","frontmatter":{"title":"What is ApptiveScript","description":"ApptiveGrid's expression language — where it shows up, what it can do, and what it can't."},"headers":[],"relativePath":"en/apptivescript/was-ist-apptivescript.md","filePath":"en/apptivescript/was-ist-apptivescript.md","lastUpdated":1787319236000}`),n={name:"en/apptivescript/was-ist-apptivescript.md"};function o(r,t,d,l,p,c){return i(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="what-is-apptivescript" tabindex="-1">What is ApptiveScript <a class="header-anchor" href="#what-is-apptivescript" aria-label="Permalink to &quot;What is ApptiveScript&quot;">​</a></h1><p><strong>ApptiveScript</strong> is ApptiveGrid&#39;s expression language. An expression is a single calculation, lookup, or condition — it takes values, does something with them, and produces a result.</p><p>You&#39;ve very likely already used ApptiveScript without noticing.</p><h2 id="every-filter-is-already-an-expression" tabindex="-1">Every filter is already an expression <a class="header-anchor" href="#every-filter-is-already-an-expression" aria-label="Permalink to &quot;Every filter is already an expression&quot;">​</a></h2><p>When you filter in a View — <em>Status equals Open</em> — ApptiveGrid writes exactly this behind the scenes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;&lt;Status&gt;&#39;).isEqualTo(&#39;Open&#39;)</span></span></code></pre></div><p>The conditions from the filter dialog are functions of the language:</p><table tabindex="0"><thead><tr><th>Condition in the interface</th><th>Function</th></tr></thead><tbody><tr><td>equals · does not equal</td><td><code>isEqualTo</code> · <code>isNotEqualTo</code></td></tr><tr><td>contains</td><td><code>contains</code></td></tr><tr><td>is greater than · is less than</td><td><code>greaterThan</code> · <code>smallerThan</code></td></tr><tr><td>is empty · is not empty</td><td><code>isEmpty</code> · <code>isNotEmpty</code></td></tr><tr><td>includes any of · none of · all of</td><td><code>includesAnyOf</code> · <code>includesNoneOf</code> · <code>includesAllOf</code></td></tr><tr><td>is before · is after</td><td><code>before</code> · <code>after</code></td></tr><tr><td>AND · OR</td><td><code>logicalAnd</code> · <code>logicalOr</code></td></tr></tbody></table><p>The same goes for relative date values: <em>today</em> is <code>today()</code>, <em>yesterday</em> is <code>today().subtractDays(1)</code>.</p><div class="tip custom-block"><p class="custom-block-title">The dialog writes along with you</p><p>If you want to write an expression by hand, the fastest way to get started is to build it via the dialog first and then look at what comes out of it. The simple selection and the expression are two views of the same thing.</p></div><h2 id="where-you-can-write-your-own-expressions" tabindex="-1">Where you can write your own expressions <a class="header-anchor" href="#where-you-can-write-your-own-expressions" aria-label="Permalink to &quot;Where you can write your own expressions&quot;">​</a></h2><p>ApptiveGrid offers a field for a custom expression in seven places:</p><table tabindex="0"><thead><tr><th>Place</th><th>Purpose</th><th>Result must be</th></tr></thead><tbody><tr><td><strong>Formula</strong> column in a Grid</td><td>Calculate values within an entry</td><td>the chosen result type</td></tr><tr><td><strong>Conditional visibility</strong> of a block, <em>Advanced</em> section</td><td>Show blocks depending on input</td><td>a boolean</td></tr><tr><td><strong>Flow transition</strong>, <em>Advanced logic</em></td><td>Continue a branch only under certain conditions</td><td>a boolean</td></tr><tr><td><strong>Text fields in Flow steps</strong></td><td>Insert values into subject, body, URL</td><td>text</td></tr><tr><td><strong>Filter</strong>, when the selection isn&#39;t enough</td><td>Combine multiple conditions</td><td>a boolean</td></tr><tr><td><strong>Relative date values</strong> in filters</td><td>&quot;7 days ago&quot; instead of a fixed date</td><td>a date</td></tr><tr><td><strong>Settings fields of type <em>Expression</em></strong> in individual Flow steps</td><td>Calculate a value instead of entering it</td><td>depends on the step</td></tr></tbody></table><p>The syntax is the same everywhere. What differs is only <strong>what an expression is allowed to start with</strong> — that depends on which values are actually available at that point. → <a href="/en/apptivescript/werte-referenzieren">Referencing values</a></p><h2 id="what-apptivescript-is-not" tabindex="-1">What ApptiveScript is not <a class="header-anchor" href="#what-apptivescript-is-not" aria-label="Permalink to &quot;What ApptiveScript is not&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Not a programming language</p><p>There are <strong>no</strong> variables, loops, custom functions, or intermediate steps. An expression is a single line that produces a value. If you need multiple steps, a <a href="/en/flows/was-ist-ein-flow">Flow</a> is the right tool — or several formula columns building on each other.</p></div><div class="warning custom-block"><p class="custom-block-title">Not the JavaScript step</p><p>The Flow step <strong>JavaScript</strong> is something different: it runs actual multi-line JavaScript, with variables and a return value. ApptiveScript is the small language for individual expressions in fields. → <a href="/en/flows/aktionen">Actions</a></p></div><div class="danger custom-block"><p class="custom-block-title">No access protection</p><p>A visibility rule decides what gets <strong>displayed</strong> — it doesn&#39;t protect any data. If you need to truly hide content, you need <a href="/en/zusammenarbeit/zugriff-beschraenken">access restrictions</a>.</p></div><h2 id="when-something-isn-t-right" tabindex="-1">When something isn&#39;t right <a class="header-anchor" href="#when-something-isn-t-right" aria-label="Permalink to &quot;When something isn&#39;t right&quot;">​</a></h2><p>The most important thing first: <strong>a broken expression usually doesn&#39;t make any noise.</strong> It produces nothing, and what happens next depends on where it is:</p><table tabindex="0"><thead><tr><th>Place</th><th>Behavior for an expression that doesn&#39;t work out</th></tr></thead><tbody><tr><td><strong>Filter</strong></td><td>The entry is considered <em>not matching</em> and disappears from the View</td></tr><tr><td><strong>Conditional visibility</strong></td><td>On an <em>error</em> the block stays visible; on an <em>empty result</em> it&#39;s hidden</td></tr><tr><td><strong>Text field in a Flow</strong></td><td>Nothing is inserted — the text stays blank at that spot</td></tr><tr><td><strong>Formula</strong></td><td>The column stays blank</td></tr></tbody></table><p>Which leads to the most important debugging rule: <strong>a field that unexpectedly stays blank, or a block that always disappears, is the classic sign of a typo in the expression</strong> — not of a permissions problem.</p><p>A name that doesn&#39;t exist isn&#39;t an error, it&#39;s simply blank. <code>formValues.get(&#39;age&#39;)</code> returns nothing if the Key is actually called <code>alter</code>. Which is why you should never type Ids and Keys — always insert them. → <a href="/en/apptivescript/werte-referenzieren">Referencing values</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptivescript/schreibweise">Syntax</a> — dots, parentheses, quotation marks</li><li><a href="/en/apptivescript/werte-referenzieren">Referencing values</a> — what an expression starts with</li><li><a href="/en/apptivescript/bedingungen">Building conditions</a> — comparisons, AND/OR, branches</li><li><a href="/en/apptivescript/editor">The expression editor</a> — token view, picker, sample result</li><li><a href="/en/referenz/apptivescript-funktionen">Function reference</a> — every function by type</li><li><a href="/en/grids/berechnete-felder">Computed fields</a> · <a href="/en/seiten/sichtbarkeit">Conditional visibility</a> · <a href="/en/flows/daten-zwischen-schritten">Passing data between steps</a></li></ul>',25)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
